import{_ as t,o as l,c as o,j as a,a as n}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/62-安全型人群的感情真的无懈可击？.md","filePath":"books/attached/62-安全型人群的感情真的无懈可击？.md","lastUpdated":1794316978000}'),r={name:"books/attached/62-安全型人群的感情真的无懈可击？.md"};function s(_,e,d,p,c,i){return l(),o("div",null,[...e[0]||(e[0]=[a("h3",{id:"安全型人群的感情真的无懈可击",tabindex:"-1"},[n("安全型人群的感情真的无懈可击？ "),a("a",{class:"header-anchor",href:"#安全型人群的感情真的无懈可击","aria-label":'Permalink to "安全型人群的感情真的无懈可击？"'},"​")],-1),a("p",null,"安全型依恋风格的人，无论自己的恋人或配偶属于何种依恋风格，都不会无限纠缠于对方。对于安全型人群来说，他们的确有这种潜力，可以与回避型、焦虑型依恋风格的人和睦相处，但事情的前提在于，安全型人格一定要将自己的安全思维模式稳固地维持下去。当安全型人群发现自己的安全感正在一点点流失，这时候他们不仅仅失去了与生俱来的优势，同时亲密关系的幸福感和满意度也会骤然下降。",-1),a("p",null,"安全型依恋风格的人，能在亲密关系中长久维持安全感有一个很重要的原因，那就是他们的非安全型伴侣在长期相处的过程中，已经逐渐建立起了良好的安全机制。美国著名心理学家玛丽·安斯沃斯（Mary Ainsworth）在亲子关系的研究中就观察到，安全型母亲有着与众不同之处。倒不是因为相比于焦虑型和回避型，安全型母亲会花更多的时间和精力去照顾孩子，而是她们有一种与生俱来的“第六感”，能够敏锐地感知到孩子在什么时候需要拥抱。她们可以感知到孩子正在萌发的不安，在这种焦虑爆发出来之前，就及时采取行动。而在孩子明显表现出焦虑不安时，安全型母亲也懂得如何安抚他们。",-1),a("p",null,"而在成人伴侣之间，也会有这样的现象产生。安全型依恋风格的成人，也懂得如何安抚自己的伴侣，照顾伴侣就是他们与生俱来的能力。而这种能力当然也能在二人世界升级为父母时延续下来。明尼苏达大学的杰弗里·辛普森和得州农机大学的斯蒂文·罗尔斯合著了图书《依恋理论与亲密关系》（Attachment Theory and Close Relationship），罗恩·坎贝尔（Lorne Campbell）与卡罗尔·威尔森（Carol Wilson）也参与了写作，书中就提到，他们发现成了家长之后，焦虑型依恋风格的女性更倾向于在亲密关系中，通过与安全型伴侣的相处，感知到伴侣的存在感、支持感以及孕期的包容感等等安全特质，从而建立起安全型依恋风格。换句话说，安全型人群用自己的敏锐和鼓励去感染自己的伴侣；同理，安全型母亲也会这样去影响孩子，将伴侣之间的安全型依恋风格转递给下一代。",-1),a("p",null,"但是值得注意的是，即使安全型依恋风格的人，天生就有能力规避不适合的潜在恋人，也善于为伴侣建立起安全机制，同样也会陷入严重的感情危机。不仅是对于没有恋爱经验的人，即使是拥有长期稳定感情的人，也会有这样的困惑。比如他们伴侣长期以来令人难以容忍的行为，就算安全型人群一再选择原谅和容忍，也一样会有忍无可忍的时候。",-1),a("p",null,"35岁的南森（Nathan）就感觉自己走投无路。他和雪莉（Shelly）结婚八年，日子一天比一天糟糕。一开始，雪莉倒是很少暴露自己的坏脾气，但是到后来却越发频繁。她的暴躁情绪愈演愈烈，不仅摔家里的东西，有一次甚至甩了南森耳光。然而他们恶劣的关系还不止于此。南森不止一次地抓到她在网上跟人调情，而且南森怀疑她在现实生活中也已经对他不忠。虽然雪莉总是扬言要分手，但是从未付诸行动，多半是在检验南森的忍耐到底有多大限度。南森总是幻想着这一切会过去，生活将恢复如常。他甚至觉得自己应该担负起令雪莉幸福的责任，不能在她经历“情绪艰难期”的时候放弃对方。而最后，雪莉告诉南森，她已经移情别恋，计划结束这段婚姻。当她决意离开后，南森尊重了她的决定，并没有再做出挽留。",-1),a("p",null,"现在，内森已经从离婚阴影渐渐走出，雪莉选择了自己想要的生活，也将他从困境中解放。他开始接受新的约会对象，开始寻找人生的另一半。然而，他总是难以解释，为什么自己会如此长时间地困在这场婚姻牢笼里。而运用依恋理论，我们可以做出如下解释。第一，正如我们所知，安全型依恋风格的人将伴侣的幸福视为己任。当他们有理由相信伴侣产生了一系列麻烦，就会立马回到对方身边共渡难关。马里奥·米库林茨和菲利普·谢弗在他们合著的《成人时期的依恋风格》（Attachment in Adulthood）一书中表示，比起其他依恋风格来，安全型的人更容易原谅伴侣的过错。他们将这种情形归纳为一种非常复杂的认知与情感能力结合方式：“原谅，对于人们的情绪调节来说是很困难的……这种调节能力包括理解对方的需求和动机，并且需要对过错一方的人格特质与带来的伤害进行宽容地换位思考……而安全型依恋风格的人，正是会对伴侣的过错进行合理化解释，因此也就更加倾向于原谅对方。”与此同时，正如我们在本章的前面部分所见，安全型人群天生就不爱从消极角度看问题，即使不进行防御和疏离，也可以将不良的情绪消解掉。",-1),a("p",null,"不过也无须太悲观，毕竟安全型依恋风格的人群有着非常强大的本能，往往能够在接触的早期，就发现哪些人不适合自己。问题就在于，一旦安全型人群判断失误，陷入了糟糕的亲密关系，特别是在那种长程而稳定的关系中，安全型人群已经将对方的幸福作为自己的责任，就或许会出现这样的情况，直到被对方抛弃才会幡然醒悟。",-1)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
